import { constructDiagram } from './internal/constructDiagram';
import { scopedReplacements, type SubtreeRange } from './diagramSubtreeEdit';
import type { AgentContextSnapshot } from '../agents/agentContext';
import type { Diagram, DiagramInput } from './diagram';
import { DiagramRevisionEditor, type DiagramEdit, type DiagramRevision, type PreparedDiagramEdit } from './diagramRevisionEditor';
import { diagramContentNodes } from './diagramContentNodes';
import { diagramRevisions } from './internal/revisionRegistry';
import { validateGeneratedDiagramEdit, type GeneratedDiagramEdit } from './generatedDiagramEdit';

export type { DiagramEdit, DiagramRevision, DiagramRevisionId } from './diagramRevisionEditor';
export interface DiagramRevisionResult extends PreparedDiagramEdit { readonly revision: DiagramRevision; replacementRanges?: SubtreeRange[] }
export type DiagramRevisionSummary = Readonly<Pick<DiagramRevision, 'id' | 'diagramId' | 'parentId'>>;
/** The parts of a template parameter that rendering needs. */
export type GenerationPromptParameter =
  | { kind: 'enum'; key: string; options: readonly { value: string; guidance: string }[] }
  | { kind: 'number'; key: string };
export interface DiagramGenerationRequest {
  /** Authoritative parsed-node -> logical-node identities, supplied by DiagramService. */
  nodeRefs?: Readonly<Record<string, string>>;
  agentContext?: AgentContextSnapshot;
  llmSessionId?: string;
  input: Omit<DiagramInput, 'revision' | 'ascii'>;
  instruction: string;
  /** Structured prompt: a validated template with options plus resolved, revision-pinned references. */
  prompt?: {
    markdown: string;
    options: Readonly<Record<string, string | number>>;
    parameters: readonly GenerationPromptParameter[];
    references: readonly unknown[];
  };
  baseRevisionId?: string;
  operation?: 'edit-diagram' | 'create-diagram' | 'extend-diagram';
  sourceMappings?: boolean;
  editRange?: SubtreeRange;
  editRanges?: SubtreeRange[];
  context?: {
    diagram: Diagram;
    connections?: readonly import('./diagramConnection').DiagramConnection[];
    selection: { startLine: number; endLine: number; startColumn: number; endColumn: number };
    projectId?: string; representationId?: string; baseRevisionId?: string;
  };
}
export interface GenerationOptions {
  signal?: AbortSignal; onProgress?: (message: string) => void;
  onAgentSession?: (sessionId: string) => void;
  onAgentContext?: (context: AgentContextSnapshot) => void;
}
export interface DiagramGenerator {
  generate(request: DiagramGenerationRequest, options: GenerationOptions): Promise<Omit<DiagramInput, 'id' | 'revision'> & { nodeCorrespondence?: Record<string, number>; replacementRanges?: SubtreeRange[] }>;
}

/** Sole content writer. Local revisions are synchronous; durable adapters flush issued records before publishing canvases. */
export interface DiagramService {
  create(input: DiagramInput): DiagramRevisionResult;
  /** Hydrate a validated standalone revision before editing after a restart/worker read. */
  importRevision(revision: DiagramRevision): void;
  getRevision(revisionId: string): DiagramRevision;
  listRevisions(diagramId: string): readonly DiagramRevisionSummary[];
  revise(baseRevisionId: string, edit: DiagramEdit): DiagramRevisionResult;
  /** Compose a reviewed revision using identities proven by retained source revisions. */
  derive(baseRevisionId: string, input: Omit<DiagramInput, 'id' | 'revision'>, refs: Record<string, number>, sources: readonly string[]): DiagramRevisionResult;
  submit(request: DiagramGenerationRequest, candidate: GeneratedDiagramEdit): DiagramRevisionResult;
  generate(request: DiagramGenerationRequest, options?: GenerationOptions): Promise<DiagramRevisionResult>;
}

export class RevisionedDiagramService implements DiagramService {
  constructor(private readonly generator?: DiagramGenerator) {}
  importRevision(revision: DiagramRevision): void {
    const nodes = diagramContentNodes(revision.diagram.content);
    const refs = nodes.map(node => revision.nodeRefs?.[node.id]);
    if (refs.some(ref => typeof ref !== 'string' || !ref) || new Set(refs).size !== refs.length) throw Error('Invalid logical node identities');
    diagramRevisions.register(revision);
  }
  create(input: DiagramInput): DiagramRevisionResult {
    const prepared = new DiagramRevisionEditor({}, () => ({})).prepareCreate(input);
    return this.issue(prepared);
  }
  getRevision(revisionId: string) { return diagramRevisions.get(revisionId); }
  listRevisions(diagramId: string): readonly DiagramRevisionSummary[] {
    return Object.freeze(diagramRevisions.list(diagramId).map(({id, diagramId, parentId}) => Object.freeze({id, diagramId, parentId})));
  }
  revise(baseRevisionId: string, edit: DiagramEdit): DiagramRevisionResult {
    const base = this.getRevision(baseRevisionId);
    const prepared = new DiagramRevisionEditor({ [base.id]: base }, () => ({ [base.diagram.id]: base.id }))
      .prepareEdit('edit', base.diagram.id, edit);
    if (prepared.diagram === base.diagram) return { ...prepared, revision: base };
    return this.issue({ ...prepared, diagram: { ...prepared.diagram, diagramId: base.diagramId, revisionId: `diagram-revision-${crypto.randomUUID()}` } }, base);
  }
  derive(baseRevisionId: string, input: Omit<DiagramInput, 'id' | 'revision'>, refs: Record<string, number>, sources: readonly string[]) {
    const base = this.getRevision(baseRevisionId), allowed = new Set<string>();
    for (const id of sources) {
      const source = this.getRevision(id);
      if (source.diagramId !== base.diagramId) throw Error('Identity source belongs to another diagram');
      Object.values(source.nodeRefs).forEach(ref => allowed.add(ref));
    }
    const editor = new DiagramRevisionEditor({ [base.id]: base }, () => ({ [base.diagram.id]: base.id }));
    const prepared = editor.prepareEdit('derive', base.diagram.id, { kind: 'replace', input,
      nodeCorrespondence: Object.fromEntries(Object.entries(refs).filter(([ref]) => Object.values(base.nodeRefs).includes(ref))) });
    const nodes = diagramContentNodes(prepared.diagram.content), identities = new Map<string, string>();
    for (const [ref, line] of Object.entries(refs)) {
      const matching = nodes.filter(node => node.line === line);
      if (!allowed.has(ref) || matching.length !== 1 || identities.has(matching[0].id)) throw Error('Invalid derived node identity');
      identities.set(matching[0].id, ref);
    }
    return this.issue({ ...prepared, diagram: { ...prepared.diagram, diagramId: base.diagramId, revisionId: `diagram-revision-${crypto.randomUUID()}` } }, base, identities);
  }
  private issue(prepared: PreparedDiagramEdit, base?: DiagramRevision, identities = new Map<string, string>()): DiagramRevisionResult {
    const reverse = new Map([...prepared.nodeIds].map(([old, next]) => [next, old]));
    const record = diagramRevisions.register({ id: prepared.diagram.revisionId, diagramId: prepared.diagram.diagramId,
      ...(base ? { parentId: base.id } : {}), diagram: prepared.diagram,
      nodeRefs: Object.fromEntries(diagramContentNodes(prepared.diagram.content).map(node => {
        const old = reverse.get(node.id);
        return [node.id, identities.get(node.id) || old && base?.nodeRefs[old] || `node-${crypto.randomUUID()}`];
      })) });
    return { ...prepared, diagram: record.diagram, revision: record };
  }
  async generate(request: DiagramGenerationRequest, options: GenerationOptions = {}) {
    if (!this.generator) throw Error('Diagram generation is unavailable in this runtime');
    options.signal?.throwIfAborted();
    if (request.baseRevisionId && this.getRevision(request.baseRevisionId).diagram.id !== request.input.id)
      throw Error('Generation base belongs to another diagram');
    const raw = await this.generator.generate(structuredClone({ ...request,
      nodeRefs: request.baseRevisionId ? this.getRevision(request.baseRevisionId).nodeRefs : {} }), options);
    options.signal?.throwIfAborted();
    return this.submit(request, { ascii: raw.ascii, structureKind: raw.structureKind ?? request.input.structureKind ?? 'diagram',
      mappings: raw.mappings ? [...raw.mappings] : undefined, replacementRanges: raw.replacementRanges }, raw.nodeCorrespondence);
  }
  submit(request: DiagramGenerationRequest, raw: GeneratedDiagramEdit, correspondence?: Record<string, number>): DiagramRevisionResult {
    const base = request.baseRevisionId ? this.getRevision(request.baseRevisionId) : undefined;
    if (base && base.diagram.id !== request.input.id) throw Error('Generation base belongs to another diagram');
    if (!base && raw.replacementRanges) throw Error('REPLACEMENT_SCOPE: new diagrams cannot include replacementRanges');
    const context = base?.diagram ?? request.context?.diagram ?? constructDiagram({ ...request.input, revision: 0, ascii: '[New diagram]', mappings: [] });
    const clean = validateGeneratedDiagramEdit(context, raw, base?.nodeRefs, request.sourceMappings);
    const generated = { ...clean, nodeCorrespondence: { ...correspondence, ...clean.nodeCorrespondence },
      source: context.sourceContext.binding, evidence: context.sourceContext.evidence };
    const ranges = request.editRanges?.length ? request.editRanges : request.editRange ? [request.editRange] : [];
    if (request.baseRevisionId && ranges.length) {
      const base = this.getRevision(request.baseRevisionId).diagram;
      if (generated.structureKind && generated.structureKind !== base.content.structure.kind) throw Error('REPLACEMENT_SCOPE: preserve the diagram structure kind');
      const { patches, outputRanges } = scopedReplacements(base, generated.ascii, ranges, generated.replacementRanges);
      const retained = base.sourceContext.mappings.flatMap(mapping => {
        if (ranges.some(range => mapping.line >= range.startLine && mapping.line <= range.endLine)) return [];
        const delta = ranges.reduce((sum, range, i) => sum + (mapping.line > range.endLine
          ? outputRanges[i].endLine - outputRanges[i].startLine - (range.endLine - range.startLine) : 0), 0);
        return [{ ...mapping, line: mapping.line + delta }];
      });
      const retainedIds = new Set(retained.map(mapping => mapping.id));
      const mappings = [...retained, ...(generated.mappings ?? []).filter(mapping => !retainedIds.has(mapping.id)
        && outputRanges.some(range => mapping.line >= range.startLine && mapping.line <= range.endLine))];
      return { ...this.revise(request.baseRevisionId, { kind: 'patches', retainMappings: !request.sourceMappings, patches, mappings, nodeCorrespondence: generated.nodeCorrespondence }), replacementRanges: outputRanges };
    }
    return request.baseRevisionId
      ? this.revise(request.baseRevisionId, { kind: 'replace', retainMappings: !request.sourceMappings, input: generated, nodeCorrespondence: generated.nodeCorrespondence })
      : this.create({ ...request.input, ...generated, id: request.input.id, revision: 0 });
  }
}

import type { Diagram } from './diagram';
import { diagramContentNodes } from './diagramContentNodes';

export interface SubtreeRange { startLine: number; endLine: number }
export function diagramSubtreeRange(diagram: Diagram, contentNodeId: string): SubtreeRange {
  const nodes = diagramContentNodes(diagram.content), root = nodes.find(node => node.id === contentNodeId);
  if (!root) throw Error('STALE_SUBTREE: select a current node');
  const ids = new Set<string>();
  const visit = (id: string) => { if (ids.has(id)) return; ids.add(id); nodes.find(node => node.id === id)?.childIds.forEach(visit); };
  visit(root.id);
  const descendants = nodes.filter(node => ids.has(node.id));
  const last = Math.max(...descendants.map(node => node.line), ...root.foldRanges.map(range => range.endLine));
  if (nodes.some(node => node.line >= root.line && node.line <= last && !ids.has(node.id)))
    throw Error('This selection is not a contiguous subtree. Choose a tree branch.');
  return { startLine: root.line, endLine: last };
}

/** A candidate contains full context, but only the selected range may differ. */
export function subtreeReplacement(base: Diagram, ascii: string, range: SubtreeRange): string {
  const before = base.content.ascii.split('\n'), after = ascii.split('\n');
  const prefix = before.slice(0, range.startLine - 1), suffix = before.slice(range.endLine);
  if (after.length < prefix.length + suffix.length || prefix.some((line, i) => line !== after[i])
    || suffix.some((line, i) => line !== after[after.length - suffix.length + i]))
    throw Error('SUBTREE_SCOPE: preserve every line outside the selected subtree exactly');
  return after.slice(prefix.length, after.length - suffix.length).join('\n');
}

export type ReplaceMode = 'diagram' | 'subnode-single' | 'multi-contiguous' | 'multi-disjoint';
export interface SubtreeTarget { contentNodeId: string; revisionId: string }
/** Resolve revision-pinned subtree roots before invoking the model. Never widen a selection. */
export function diagramReplacementRanges(diagram: Diagram, mode: ReplaceMode, subtree?: SubtreeTarget, subtrees?: SubtreeTarget[]): SubtreeRange[] {
  if (mode === 'diagram') {
    if (subtree || subtrees) throw Error('REPLACEMENT_SCOPE: diagram mode cannot include subtree targets');
    return [];
  }
  const targets = mode === 'subnode-single' ? subtree && !subtrees ? [subtree] : [] : !subtree ? subtrees ?? [] : [];
  if (targets.length < (mode === 'subnode-single' ? 1 : 2)) throw Error('REPLACEMENT_SCOPE: supply subtree for subnode-single, or at least two subtrees for a multi mode');
  if (targets.some(target => target.revisionId !== diagram.content.revisionId)) throw Error('VERSION_CONFLICT: selected subtree changed; select it again');
  const ranges = targets.map(target => ({ ...diagramSubtreeRange(diagram, target.contentNodeId), id: target.contentNodeId })).sort((a, b) => a.startLine - b.startLine);
  if (ranges.some((range, i) => i > 0 && range.startLine <= ranges[i - 1].endLine)) throw Error('REPLACEMENT_SCOPE: subtree targets must not overlap or repeat');
  if (mode === 'multi-contiguous') {
    if (ranges.some((range, i) => i > 0 && diagram.content.ascii.split('\n').slice(ranges[i - 1].endLine, range.startLine - 1).some(line => line.trim())))
      throw Error('REPLACEMENT_SCOPE: multi-contiguous requires adjacent subtrees');
    return [{ startLine: ranges[0].startLine, endLine: ranges.at(-1)!.endLine }];
  }
  if (mode === 'multi-disjoint' && ranges.some((range, i) => i > 0 && range.startLine === ranges[i - 1].endLine + 1))
    throw Error('REPLACEMENT_SCOPE: adjacent subtrees use multi-contiguous');
  return ranges.map(({ startLine, endLine }) => ({ startLine, endLine }));
}

/** Output line ranges correspond, in order, to the requested input ranges. Empty output uses endLine = startLine - 1. */
export function scopedReplacements(base: Diagram, ascii: string, ranges: readonly SubtreeRange[], outputRanges?: readonly SubtreeRange[]) {
  const before = base.content.ascii.split('\n'), after = ascii.split('\n');
  if (!ranges.length) throw Error('REPLACEMENT_SCOPE: expected at least one range');
  if (ranges.length === 1 && !outputRanges) {
    const range = ranges[0];
    subtreeReplacement(base, ascii, range);
    outputRanges = [{ startLine: range.startLine, endLine: after.length - (before.length - range.endLine) }];
  }
  if (!outputRanges || outputRanges.length !== ranges.length) throw Error('REPLACEMENT_SCOPE: supply one output range for every selected range');
  let oldEnd = 0, newEnd = 0;
  const patches = ranges.map((range, i) => {
    const output = outputRanges![i];
    for (const [r, length, end] of [[range, before.length, oldEnd], [output, after.length, newEnd]] as const) {
      if (!Number.isInteger(r.startLine) || !Number.isInteger(r.endLine) || r.startLine <= end || r.startLine > length + 1 || r.endLine < r.startLine - 1 || r.endLine > length)
        throw Error('REPLACEMENT_SCOPE: invalid or overlapping line ranges');
    }
    const gap = before.slice(oldEnd, range.startLine - 1), nextGap = after.slice(newEnd, output.startLine - 1);
    if (gap.length !== nextGap.length || gap.some((line, j) => line !== nextGap[j])) throw Error('REPLACEMENT_SCOPE: preserve every line outside the selected ranges exactly');
    oldEnd = range.endLine; newEnd = output.endLine;
    return { start: range.startLine, end: range.endLine, patch: after.slice(output.startLine - 1, output.endLine) };
  });
  const tail = before.slice(oldEnd), nextTail = after.slice(newEnd);
  if (tail.length !== nextTail.length || tail.some((line, i) => line !== nextTail[i])) throw Error('REPLACEMENT_SCOPE: preserve every line outside the selected ranges exactly');
  return { patches, outputRanges: [...outputRanges] };
}

